}
a {
color: #337ab7;
}
#buttons  a {
display: inline-block;
background-color: #f8f8f8;
padding: 4px 20px;
margin: 0 4px 4px 0; 
cursor: pointer;
text-decoration: none;
font-size: 18px;
color: #333;
}
#buttons  a:hover {
background-color: #286090;
}
#buttons  a.active {
background-color: #337ab7;
}
#buttons  a:hover,
#buttons  a.active {
color: #fff;
}
.data,
.hide {
display: none;
}
.container {
width: 1000px;
margin: 40px auto;
}
.table-col-link {
width: 400px;
}
/style
script
function arrayfy(nodeList) {
return Array.prototype.slice.call(nodeList, 0);
}
function exractDatasets() {
// Logical datasets.
// All elements with data class.
var datasets = arrayfy(document.querySelectorAll(&apos;.data&apos;));
return datasets.map(function(dataset, index) {
var rows = [];
var lines = dataset.innerHTML.split(/\r?\n/);
lines.forEach(function(line) {
var match = line.match(/^(.+)\|(.+)\|(.+)$/);
if (match) {
rows.push({
url: match[1].trim(),
label: match[2].trim(),
description: match[3].trim()
});
}
});
var title = dataset.getAttribute(&apos;data-tab&apos;);
return { title: title, rows: rows, index: index };
});
}
function showDatasets(datasets) {                
// Actual table part.
function createTable(dataset) {
// Header
var linkCell = document.createElement(&apos;th&apos;);
linkCell.innerHTML = &apos;Link&apos;;
var descriptionCell = document.createElement(&apos;th&apos;);
descriptionCell.innerHTML = &apos;Description&apos;;
var tr = document.createElement(&apos;tr&apos;);
tr.appendChild(linkCell);
tr.appendChild(descriptionCell);
// Column widths.
var linkCol = document.createElement(&apos;col&apos;);
linkCol.className = &apos;table-col-link&apos;;
var colgroup = document.createElement(&apos;colgroup&apos;);
colgroup.appendChild(linkCol);
var table = document.createElement(&apos;table&apos;);
table.appendChild(colgroup);
table.appendChild(tr);
// Rest of the table.
dataset.rows.forEach(function(row) {
// Single table row.                        
var anchor = document.createElement(&apos;a&apos;);
anchor.href = row.url;
anchor.innerHTML = row.label;
var linkCell = document.createElement(&apos;td&apos;);
linkCell.appendChild(anchor);
var descriptionCell = document.createElement(&apos;td&apos;);
descriptionCell.innerHTML = row.description;
var tr = document.createElement(&apos;tr&apos;);
tr.appendChild(linkCell);
tr.appendChild(descriptionCell);                        
table.appendChild(tr);
});
// Also add title.
var h1 = document.createElement(&apos;h1&apos;);
h1.innerHTML = dataset.title;
var ret = document.createDocumentFragment();
ret.appendChild(h1);
ret.appendChild(table);
return ret;
}
// Tab selector button.
function createButton(dataset) {
var anchor = document.createElement(&apos;a&apos;);
anchor.href = &apos;#tab-&apos; + dataset.index;
anchor.innerHTML = dataset.title;
return anchor;
}
// Tab components.
function createTab(dataset) {
var button = createButton(dataset);
return {
dataset: dataset,
button: button,
create: function() {
return createTable(dataset);
}
};
}                
// Current table area.
var table = document.getElementById(&apos;table&apos;);
// Tab buttons.
var buttons = document.getElementById(&apos;buttons&apos;);
var tabs = [];
// Creates menu and logical representation of tabs.
datasets.forEach(function(dataset) {
var tab = createTab(dataset);                    
buttons.appendChild(tab.button);
tabs.push(tab);
});
// Updates current tab based on the
// current URL fragment value.
function updateTab() {
var match = location.href.match(/#tab-(\d+)$/);
if (match) {
var index = parseInt(match[1], 10);
// Resets active states.
arrayfy(buttons.childNodes).forEach(function(button) {
button.className = &apos;&apos;;
});
// Sets new active state.
buttons.childNodes[index].className = &apos;active&apos;;
// Drop table contents.
table.innerHTML = &apos;&apos;;
// Set document title.
document.title = tabs[index].dataset.title;
// Set new contents.
table.appendChild(tabs[index].create());                        
}
}
// Sets initially shown tab.
function initTab() {
var match = location.href.match(/#tab-(\d+)$/);
if (match) {
updateTab();
} else {
window.location.hash = &apos;#tab-0&apos;;
}
}
// Display tab based on URL hash fragment.
window.addEventListener(&apos;hashchange&apos;, function() {
updateTab();
}, false);
initTab();
}
/script
/head
body
